const $=s=>document.querySelector(s), root=$('#app');
const escape=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const money=v=>v===null||v===undefined||v===''?'Não definido':Number(v).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const pretty=t=>t?new Date(t).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}):'Não disponível';
const svg=(name)=>{
 const set={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',map:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3zM9 3v15M15 6v15"/>',route:'<path d="M3 18c6 0 5-12 11-12s2 9 7 9"/><circle cx="3" cy="18" r="2"/><circle cx="21" cy="15" r="2"/>',users:'<circle cx="9" cy="8" r="4"/><path d="M2 21v-3a5 5 0 0 1 5-5h4a5 5 0 0 1 5 5v3M17 3a4 4 0 0 1 0 8m2 3a5 5 0 0 1 3 5v2"/>',box:'<path d="m12 2 9 5-9 5-9-5 9-5ZM3 7v10l9 5 9-5V7M12 12v10"/>',layers:'<path d="m12 2 9 5-9 5-9-5 9-5ZM3 12l9 5 9-5M3 17l9 5 9-5"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M2 12h3m14 0h3M12 2v3m0 14v3M4.93 4.93l2.12 2.12m9.9 9.9 2.12 2.12M4.93 19.07l2.12-2.12M16.95 7.05l2.12-2.12"/>',play:'<path d="m8 5 11 7-11 7z"/>',pause:'<path d="M7 5h4v14H7zM15 5h4v14h-4z"/>',refresh:'<path d="M20 11a8 8 0 0 0-14-5L3 9m0-6v6h6m-5 4a8 8 0 0 0 14 5l3-3m0 6v-6h-6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',plus:'<path d="M12 4v16M4 12h16"/>',pin:'<path d="M20 10c0 5-8 12-8 12S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2"/>',check:'<path d="m4 12 5 5L20 6"/>',clock:'<circle cx="12" cy="12" r="10"/><path d="M12 7v5l4 3"/>',shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/><path d="m9 12 2 2 4-4"/>'};
 return `<svg viewBox="0 0 24 24" width="17" height="17" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${set[name]||set.grid}</svg>`;
};
const defaultData=()=>createSingleExampleData(localDate());
const AREA_SEGMENTS=Object.freeze({A:{label:'Área azul · Público A',color:'#3b82f6'},B:{label:'Área amarela · Público B',color:'#facc15'},C:{label:'Área cinza · Público C',color:'#9ca3af'},'D+':{label:'Área vermelha · Público D+',color:'#ef4444'}});
function segmentOptions(value=''){return '<option value="">Não classificada</option>'+Object.entries(AREA_SEGMENTS).map(([id,v])=>`<option value="${id}" ${value===id?'selected':''}>${v.label}</option>`).join('');}
function areaLegend(){return `<div class="area-legend" aria-label="Classificação de públicos por área">${Object.values(AREA_SEGMENTS).map(v=>`<span><i style="background:${v.color}"></i>${v.label}</span>`).join('')}</div>`;}
const STORAGE='st1-pap-web-v5-exemplo-unico';
function safeRead(){try{const d=JSON.parse(localStorage.getItem(STORAGE));if(d&&d.version===EXAMPLE_VERSION&&Array.isArray(d.plans)&&Array.isArray(d.sellers)&&Array.isArray(d.zones)&&Array.isArray(d.ctos)&&Array.isArray(d.rules))return d;}catch{}return defaultData();}
let data=safeRead();
data.visits=(data.visits||[]).map(v=>({...v,date:v.date||localDate(),place:v.place||'Local não informado',stage:STAGES.includes(v.stage)?v.stage:v.stage.includes('Proposta')?'Proposta':'Visitada'}));
data.assignments ||= []; data.activity ||= [];data.itineraries ||= {};
data.referencePoints ||= []; data.imports ||= [];
data.zones.forEach(z=>{if(AREA_SEGMENTS[z.audience]){z.category=z.audience;z.color=AREA_SEGMENTS[z.audience].color;}});
const filters={date:'',stage:'all',search:''};
const itinerary={sellerId:data.sellers[0]?.id||0,date:localDate()};
function audit(message){data.activity.unshift({at:new Date().toISOString(),message});data.activity=data.activity.slice(0,200);}

const state={importPreview:null,importFocus:null,page:'overview',sellerId:data.sellers[0]?.id||0,team:'all',mapRegion:'sa_luis',map:null,selectedPoint:data.visits[0]?{lat:data.visits[0].lat,lon:data.visits[0].lon}:null,routeIndex:Math.max(0,(data.sellers[0]?.routePoints?.length||1)-1),playing:false,timer:null,positions:{},layers:{showZones:true,showSellers:true,showCtos:true},result:null,toasts:0};
const save=()=>{try{localStorage.setItem(STORAGE,JSON.stringify(data));return true;}catch{notify('O armazenamento local está cheio ou indisponível. A importação não será gravada.','error');return false;}};
const routeFor=s=>Array.isArray(s?.routePoints)?s.routePoints.filter(p=>Number.isFinite(Number(p.lat))&&Number.isFinite(Number(p.lon))&&p.at):[];
const routes=()=>data.sellers.reduce((a,s)=>(a[s.id]=routeFor(s),a),{});
const dtr=()=>routes()[state.sellerId]||[];
function positionFor(s){const p=s?.position;return p&&Number.isFinite(Number(p.lat))&&Number.isFinite(Number(p.lon))?p:null;}
function asMapData(){return {...data,sellers:data.sellers.filter(s=>state.team==='all'||s.team===state.team).map(s=>({...s,position:positionFor(s)}))};}
function routeMeters(points){let m=0;const R=Math.PI/180;for(let i=1;i<points.length;i++){const p=points[i-1],q=points[i],dlat=(q.lat-p.lat)*R,dlon=(q.lon-p.lon)*R,a=Math.sin(dlat/2)**2+Math.cos(p.lat*R)*Math.cos(q.lat*R)*Math.sin(dlon/2)**2;m+=6371000*2*Math.asin(Math.sqrt(Math.min(1,a)));}return m;}
function findTerritory(p){const hits=data.zones.filter(z=>insideZone(p,z.geometry));return hits.length===1?hits[0]:null;}
function insideRing(p,ring){let hit=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const a=ring[i],b=ring[j];if((a[1]>p.lat)!==(b[1]>p.lat)&&p.lon<(b[0]-a[0])*(p.lat-a[1])/(b[1]-a[1])+a[0])hit=!hit;}return hit;}
function insideZone(p,g){if(!g)return false;const polygons=g.type==='Polygon'?[g.coordinates]:g.type==='MultiPolygon'?g.coordinates:[];return polygons.some(rings=>rings.length&&insideRing(p,rings[0])&&!rings.slice(1).some(r=>insideRing(p,r)));}
function notify(message,type='ok'){const old=$('.toast');old?.remove();const n=document.createElement('div');n.setAttribute('role','status');n.className='toast '+(type==='error'?'error':'');n.textContent=message;document.body.append(n);setTimeout(()=>n.remove(),4300);}
function stat(title,value,description,accent=false){return `<div class="stat ${accent?'accent':''}"><div class="k">${escape(title)}</div><div class="v">${escape(value)}</div><div class="hint">${escape(description)}</div></div>`;}
const nav=[['overview','Central de operação','map'],['routes','Rotas e jornada','route'],['planning','Planejamento de campo','clock'],['visits','Visitas e oportunidades','pin'],['people','Equipes PAP','users'],['coverage','Territórios e CTOs','layers'],['products','Ofertas e elegibilidade','box'],['reports','Produtividade','grid']];
const titles={itinerary:['Roteiro de visitas','Organize as paradas por vendedor e data'],sales:['Conexão com o Sales','Dados comerciais a serviço da operação de campo'],visits:['Visitas e oportunidades','Acompanhe cada etapa da operação de campo'],planning:['Planejamento de campo','Distribua territórios e metas diárias entre as equipes'],reports:['Resultados da operação','Indicadores calculados a partir dos registros filtrados'],admin:['Administração da central','Preferências, dados locais e prontidão das integrações'],overview:['Operação porta a porta','Controle territorial, vendedores e ofertas em um só lugar'],routes:['Rastreamento e rotas','Histórico, reprodução e eventos de deslocamento da equipe'],people:['Equipes de campo','Distribuição operacional de vendedores e supervisores'],products:['Catálogo de ofertas','Planos e elegibilidade por território'],coverage:['Inteligência de cobertura','Geometrias, CTOs e capacidade técnica']};
function chrome(){const [title,subtitle]=titles[state.page];return `<aside class="sidebar"><div class="brand"><div class="brand-logo">S1</div><div><strong>ST1 SALES</strong><small>OPERAÇÃO DE CAMPO</small></div></div><div class="side-menu"><div class="group-label">CENTRAL DE OPERAÇÕES</div>${nav.map(([id,name,ic])=>`<button class="menu-btn ${state.page===id?'active':''}" data-page="${id}" aria-label="${escape(name)}" aria-current="${state.page===id?'page':'false'}" title="${escape(name)}">${svg(ic)}<span>${escape(name)}</span></button>`).join('')}</div><div class="side-bottom"><div class="lab"><i class="status-dot"></i> LOGIN APRESENTAÇÃO</div><p>Visualização local sem autenticação operacional.</p></div></aside><div class="main"><div class="topbar"><div class="crumb">ST1 / <b>SALES</b> / PAP / ${escape(state.page.toUpperCase())}</div><div class="top-right"><span>PAP / GESTÃO WEB</span><span class="top-sep"></span><span class="pill">● DADOS FICTÍCIOS</span></div></div><main class="workspace" id="main-content" tabindex="-1"><div class="lead"><div><div class="eyebrow">ST1 SALES / GESTÃO DE CAMPO</div><h1>${title}</h1><p>${subtitle}</p></div><div class="lead-actions"><button type="button" class="btn ghost" data-action="export">${svg('download')} Exportar exemplo</button><button type="button" class="btn primary" data-page="routes">${svg('route')} Ver trajetos</button></div></div>${page()}<div class="foot"><span>ST1 SALES // PAP WEB • HOMOLOGAÇÃO</span><span>MAPAS © OPENSTREETMAP • LOCALIZAÇÕES FICTÍCIAS</span></div></main></div>`;}
function teamOptions(selected='all'){return `<option value="all" ${selected==='all'?'selected':''}>Todas as equipes</option>${[...new Set(data.sellers.map(s=>s.team))].map(t=>`<option value="${escape(t)}" ${selected===t?'selected':''}>${escape(t)}</option>`).join('')}`;}
function overview(){const sellers=asMapData().sellers,active=sellers.length;
 return `<div class="stats">${stat('VENDEDORES CADASTRADOS',active,'Um vendedor fictício')}${stat('POSIÇÕES GPS',sellers.filter(s=>s.position).length,'Posição fictícia, não rastreamento')}${stat('TERRITÓRIOS',data.zones.length,'Polígono ilustrativo')}${stat('PLANOS LOCAIS',data.plans.filter(p=>p.active).length,'Preço ilustrativo, não oficial',true)}</div>
 <div class="map-grid-layout"><div class="panel"><div class="panel-head"><div><div class="kicker">MAPA DE COBERTURA</div><h2>Visão territorial</h2></div><span class="pill">${svg('pin')} ${escape(MAP_REGIONS[state.mapRegion]?.label||MAP_REGIONS.all.label)}</span></div>${mapToolbar()}<div id="operation-map" class="map-viewport"></div>${mapFooter()}</div>
 <div class="panel"><div class="panel-head"><div><div class="kicker">SALA DE OPERAÇÃO</div><h2>Vendedores no mapa</h2></div><span class="pill">${active} PROFISSIONAIS</span></div><div class="inspector"><label class="select input-label">Filtrar equipe<select id="team-filter">${teamOptions(state.team)}</select></label><div class="inner-list">${sellerRows(sellers)}</div><div class="divider"></div><div class="side-inspector-head"><h3 class="section-title">Ponto de instalação</h3>${state.selectedPoint?'<span class="mini-badge warn">SEM CONSULTA</span>':''}</div><div class="hint-block">Clique no mapa para selecionar o ponto de instalação. O GPS de um vendedor nunca determina elegibilidade comercial.</div>${eligibilityForm()}</div></div></div>`;}
function mapToolbar(){return `<div class="map-toolbar"><div class="map-city-quick" role="group" aria-label="Centralizar mapa por munic\u00edpio">${Object.entries(MAP_REGIONS).map(([id,place])=>`<button type="button" data-map-city="${id}" class="map-city ${state.mapRegion===id?'selected':''}">${escape(place.label)}</button>`).join('')}</div><div class="map-layer-switches"><label><input type="checkbox" data-layer="showZones" ${state.layers.showZones?'checked':''}> Territ\u00f3rios LOCAL</label><label><input type="checkbox" data-layer="showSellers" ${state.layers.showSellers?'checked':''}> Vendedores</label><label><input type="checkbox" data-layer="showCtos" ${state.layers.showCtos?'checked':''}> CTOs</label></div></div>`;}
function mapFooter(){return `${areaLegend()}<div class="map-footer"><span><span class="legend"><i></i>GPS sem conexão</span><span class="legend"><i class="zone"></i>Cobertura</span><span class="legend"><i class="cto"></i>CTO</span></span><span id="map-coord">${state.selectedPoint?`${state.selectedPoint.lat.toFixed(5)}, ${state.selectedPoint.lon.toFixed(5)}`:'Clique para indicar o imóvel'}</span></div>`;}
function sellerRows(users){return users.map(s=>`<button class="seller-item ${state.sellerId===s.id?'selected':''}" data-select-seller="${s.id}"><span class="avatar">${String(s.id).padStart(2,'0')}</span><span class="seller-meta"><strong>${escape(s.name)}</strong><small>${escape(s.team)}</small></span><span class="mini-badge warn">EXEMPLO</span></button>`).join('')||'<div class="empty">Nenhum profissional disponível nesta equipe.</div>';}
function eligibilityForm(){const p=state.selectedPoint,z=p?findTerritory(p):null;return `<form id="eligibility-form" class="form-stack"><label class="input-label">Plano<select name="planId" class="input" required><option value="">Escolha um plano</option>${data.plans.filter(x=>x.active).map(x=>`<option value="${x.id}" ${x.example?'selected':''}>${escape(x.name)}</option>`).join('')}</select></label><label class="input-label">CTO<select name="ctoId" class="input" required><option value="">Escolha CTO</option>${data.ctos.map(c=>`<option value="${c.id}" ${c.example?'selected':''}>${escape(c.name)} · ${c.ports_free} portas</option>`).join('')}</select></label><div class="mini-row"><span>Território</span><strong>${z?escape(z.name):p?'Fora de zona única':'Não selecionado'}</strong></div><button type="submit" class="btn primary" ${data.exampleOnly&&p&&z?'':'disabled'}>${svg('shield')} Testar cenário fictício</button>${state.result?`<div class="callout ${state.result.kind==='ok'?'':'warn'}"><strong>${escape(state.result.status)}</strong><div>${escape(state.result.message)}</div><small>Nenhuma autorização de venda foi emitida.</small></div>`:''}</form>`;}
function evaluate(input){const p=state.selectedPoint,z=p?findTerritory(p):null,plan=data.plans.find(x=>x.id===Number(input.planId)),cto=data.ctos.find(x=>x.id===Number(input.ctoId));if(!data.exampleOnly||!z?.example||!plan?.example||!cto?.example)return {status:'VERIFICAÇÃO OFICIAL INDISPONÍVEL',kind:'warn',message:'Somente o cenário fictício é testado aqui. A viabilidade real exige o ST1 Sales.'};if(cto.zone_id!==z.id||cto.ports_free<1||cto.status!=='online'||!plan.active)return {status:'EXEMPLO REPROVADO',kind:'warn',message:'Neste exemplo, a CTO não atende às condições selecionadas.'};const rule=data.rules.find(r=>r.zone_id===z.id&&r.plan_id===plan.id);if(rule?.decision!=='allow')return {status:'EXEMPLO REPROVADO',kind:'warn',message:'Não há regra ilustrativa permitindo a oferta.'};return {status:'EXEMPLO ILUSTRATIVO — CONDIÇÕES ATENDIDAS',kind:'warn',message:'Resultado calculado apenas com dados inventados. Não houve consulta à rede, ao IXC ou autorização comercial.'};}
function routesPage(){const seller=data.sellers.find(s=>s.id===state.sellerId)||data.sellers[0],points=seller?routeFor(seller):[],index=Math.max(0,Math.min(state.routeIndex,points.length-1)),clip=points.slice(0,index+1),distance=routeMeters(clip)/1000;
 const current=points[index];return `<div class="stats route-stats">${stat('PONTOS DE GPS',clip.length,'Amostras fictícias')}${stat('DISTÂNCIA REGISTRADA',distance.toLocaleString('pt-BR',{maximumFractionDigits:2})+' km','Distância entre amostras',true)}${stat('HORÁRIO DO REGISTRO',current?pretty(current.at):'—','Registros de exemplo')}</div>
 <div class="map-grid-layout"><div class="panel"><div class="panel-head"><div><div class="kicker">RASTREAMENTO / REPLAY</div><h2>Trilhas da operação</h2></div><span class="pill">${svg('route')} ${seller?escape(seller.name):'Nenhum vendedor'}</span></div>${mapToolbar()}<div id="operation-map" class="map-viewport"></div><div class="route-ctrl"><button class="btn primary sm" data-action="play" ${points.length?'':'disabled'}>${svg(state.playing?'pause':'play')} ${state.playing?'Pausar':'Reproduzir'}</button><input type="range" id="route-range" min="0" max="${Math.max(0,points.length-1)}" value="${index}" ${points.length?'':'disabled'} aria-label="Reproduzir rota"><time id="route-current-time">${current?pretty(current.at):'Sem dados de GPS'}</time></div>${mapFooter()}</div>
 <div class="panel"><div class="panel-head"><div><div class="kicker">SEQUÊNCIA DE CAMPO</div><h2>Rota selecionada</h2></div><button class="btn sm ghost" data-action="route-export">${svg('download')} GeoJSON</button></div><div class="inspector"><label class="select input-label">Escolha o vendedor<select id="route-seller">${data.sellers.map(s=>`<option value="${s.id}" ${seller?.id===s.id?'selected':''}>${escape(s.name)}</option>`).join('')}</select></label><div class="mini-row"><span>Origem do posicionamento</span><strong>EXEMPLO • SEM GPS REAL</strong></div><div class="mini-row"><span>Total de pontos</span><strong>${points.length}</strong></div><div class="mini-row"><span>Distância total</span><strong>${(routeMeters(points)/1000).toLocaleString('pt-BR',{maximumFractionDigits:2})} km</strong></div><div class="mini-row"><span>Última amostra</span><strong>${current?pretty(current.at):'—'}</strong></div><div class="divider"></div><h3 class="section-title">Linha do tempo</h3><div class="timeline"><div class="timeline-entry"><span class="node"></span><div><strong>Início do trajeto</strong><small>${points[0]?pretty(points[0].at):'—'}</small></div></div>${data.visits.filter(v=>v.sellerId===seller?.id).map(v=>`<div class="timeline-entry"><span class="node"></span><div><strong>${escape(v.stage)}</strong><small>${escape(v.at)} • local informado</small></div></div>`).join('')}<div class="timeline-entry"><span class="node"></span><div><strong>Fim do trajeto</strong><small>${points.at(-1)?pretty(points.at(-1).at):'—'}</small></div></div></div><div class="callout warn">Trajeto composto por coordenadas inventadas para verificação visual. A conexão com GPS real e aplicativo PAP ainda depende de integração autenticada.</div></div></div></div>`;}
function peoplePage(){const users=data.sellers.filter(s=>state.team==='all'||s.team===state.team);return `<div class="panel"><div class="panel-head"><div><div class="kicker">ORGANIZAÇÃO DO CAMPO</div><h2>Profissionais de campo</h2></div><span class="pill">${users.length} PROFISSIONAIS</span></div><div class="panel-pad"><div class="split-toolbar"><label class="input-label">Equipe<select id="team-filter" class="input">${teamOptions(state.team)}</select></label><button class="btn ghost sm" data-action="people-add" disabled>${svg('plus')} Cadastrar pelo Sales</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Profissional</th><th>Equipe</th><th>GPS</th><th>Status</th><th></th></tr></thead><tbody>${users.map(s=>`<tr><td><strong>${escape(s.name)}</strong></td><td>${escape(s.team)}</td><td>Fictício</td><td><span class="mini-badge warn">EXEMPLO</span></td><td><button class="table-action" data-select-seller="${s.id}" data-page="routes">Rota</button> <button class="table-action danger" data-remove-seller="${s.id}">Excluir</button></td></tr>`).join('')||'<tr><td colspan="5">Nenhum profissional sincronizado</td></tr>'}</tbody></table></div></div></div>`; }
function productsPage(){return `<div class="two-col"><div class="panel"><div class="panel-head"><div><div class="kicker">CATÁLOGO LOCAL</div><h2>Produtos e regras territoriais</h2></div><span class="pill">${data.plans.filter(x=>x.active).length} ATIVOS</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Plano</th><th>Segmento</th><th>Preço</th><th>Estado</th><th></th></tr></thead><tbody>${data.plans.map(p=>`<tr><td><strong>${escape(p.name)}</strong><small style="display:block;color:#778698;margin-top:5px">Velocidade: ${escape(p.speed||'não definida')}</small></td><td>${escape(p.segment)}</td><td>${money(p.price)}</td><td><button type="button" class="table-action" data-plan-toggle="${p.id}">${p.active?'Ativo':'Inativo'}</button></td><td><button type="button" class="table-action danger" data-plan-remove="${p.id}">Remover</button></td></tr>`).join('')}</tbody></table></div><div class="panel-pad"><h3 class="section-title">Regras por território</h3><div class="table-wrap"><table class="table"><thead><tr><th>Território</th><th>Plano</th><th>Regra</th></tr></thead><tbody>${data.zones.flatMap(z=>data.plans.map(p=>{const r=data.rules.find(r=>r.zone_id===z.id&&r.plan_id===p.id);return `<tr><td>${escape(z.name)}</td><td>${escape(p.name)}</td><td><select class="input" data-rule-zone="${z.id}" data-rule-plan="${p.id}"><option value="clear" ${!r?'selected':''}>Sem regra</option><option value="allow" ${r?.decision==='allow'?'selected':''}>Permitido (local)</option><option value="deny" ${r?.decision==='deny'?'selected':''}>Negado (local)</option></select></td></tr>`;})).join('')}</tbody></table></div></div></div><div class="panel panel-pad"><div class="kicker">CADASTRO LOCAL DE OFERTA</div><h2>Rascunho de plano</h2><p>Rascunhos aqui salvos não são ofertas oficiais. Os planos válidos devem vir do catálogo autenticado do ST1 Sales.</p><form id="plan-form" class="form-stack"><label class="input-label">Nome do plano<input class="input" name="name" required minlength="3" maxlength="75" placeholder="Nome do plano"></label><label class="input-label">Segmento<select class="input" name="segment"><option>Residencial</option><option>PME</option><option>Indoor</option></select></label><label class="input-label">Velocidade (opcional)<input class="input" name="speed" maxlength="25" placeholder="Informe a velocidade"></label><label class="input-label">Preço local (opcional)<input class="input" name="price" type="number" min="0" max="100000" step="0.01" placeholder="Não definido"></label><button type="submit" class="btn primary">${svg('plus')} Salvar no navegador</button></form></div></div>`;}

function importPreviewPanel() {
 const p=state.importPreview;
 if(!p)return '';
 const folders=p.folders.slice(0,7).map(f=>'<span class="import-chip">'+escape(f)+'</span>').join('');
 const names=[...p.polygons.slice(0,3).map(x=>'Área: '+x.name),...p.points.slice(0,3).map(x=>(x.possibleCto?'Possível CTO: ':'Ponto: ')+x.name)];
 const sample=names.map(x=>'<li>'+escape(x)+'</li>').join('');
 return '<section class="import-preview" aria-live="polite"><div class="import-preview-head"><h3>Prévia da importação</h3><span class="pill">'+escape(p.format)+'</span></div>'+
 '<p><strong>'+escape(p.fileName)+'</strong>'+(p.internalName?' · KML interno: '+escape(p.internalName):'')+'</p>'+
 '<div class="import-metrics"><span><strong>'+p.polygons.length+'</strong> polígonos</span><span><strong>'+p.ctoCandidates+'</strong> possíveis CTOs</span><span><strong>'+(p.points.length-p.ctoCandidates)+'</strong> outros pontos</span></div>'+
 '<p class="import-note">Camada escolhida: '+escape(AREA_SEGMENTS[p.audience]?.label||'Não classificada')+'. Estes elementos ainda não foram gravados nem representam cobertura validada.</p>'+
 (folders?'<div class="import-folders"><strong>Pastas/camadas:</strong> '+folders+'</div>':'')+
 (sample?'<ul class="import-sample">'+sample+'</ul>':'')+
 (p.ignored?'<p class="import-note">'+p.ignored+' elemento(s) não suportado(s) ignorado(s).</p>':'')+
 '<div class="import-actions"><button class="btn primary" type="button" data-action="confirm-import">Confirmar importação local</button><button class="btn ghost" type="button" data-action="cancel-import">Cancelar</button></div></section>';
}
function importListPanel() {
 if(!data.imports?.length)return '';
 return '<div class="divider"></div><h3 class="section-title">Arquivos importados neste navegador</h3>'+
 data.imports.map(i=>'<div class="import-file"><div><strong>'+escape(i.fileName)+'</strong><small>'+
 i.polygons+' polígonos · '+i.points+' pontos · não sincronizado</small></div>'+
 '<button class="table-action danger" type="button" data-import-remove="'+escape(i.id)+'">Remover</button></div>').join('');
}
function importFocusFor(preview){
 const p=preview.points[0];
 if(p)return {lat:p.lat,lon:p.lon};
 const ring=preview.polygons[0]?.geometry?.type==='Polygon'?
  preview.polygons[0].geometry.coordinates[0]:
  preview.polygons[0]?.geometry?.coordinates?.[0]?.[0];
 if(!ring?.length)return null;
 return {lat:ring.reduce((a,v)=>a+v[1],0)/ring.length,lon:ring.reduce((a,v)=>a+v[0],0)/ring.length};
}
function commitTerritoryImport(){
 const p=state.importPreview;
 if(!p){notify('Selecione e analise um arquivo primeiro.','error');return;}
 const old=JSON.stringify(data),batch='arquivo-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7);
 const color=AREA_SEGMENTS[p.audience]?.color||'#7299bd',audience=AREA_SEGMENTS[p.audience]?p.audience:'';
 let zoneId=Math.max(0,...data.zones.map(z=>z.id)),ctoId=Math.max(0,...data.ctos.map(c=>c.id));
 for(const x of p.polygons){
  data.zones.push({id:++zoneId,name:x.name,geometry:x.geometry,category:audience||'NÃO CLASSIFICADO',audience,color,
   source:'ARQUIVO LOCAL',sourceFolder:x.folder,importBatchId:batch});
 }
 for(const x of p.points){
  if(x.possibleCto){
   data.ctos.push({id:++ctoId,name:x.name,zone_id:null,lat:x.lat,lon:x.lon,ports_free:null,status:'unverified',
    verified_at:null,source:'ARQUIVO LOCAL',sourceFolder:x.folder,importBatchId:batch});
  }else{
   data.referencePoints.push({name:x.name,lat:x.lat,lon:x.lon,sourceFolder:x.folder,importBatchId:batch});
  }
 }
 data.imports.unshift({id:batch,fileName:p.fileName,format:p.format,polygons:p.polygons.length,points:p.points.length,
  importedAt:new Date().toISOString()});
 if(!save()){data=JSON.parse(old);return;}
 state.importFocus=importFocusFor(p);state.importPreview=null;
 render();notify('Arquivo importado apenas neste navegador; sem sincronização com a rede ST1.');
}
function removeTerritoryImport(batch){
 const entry=data.imports?.find(i=>i.id===batch);if(!entry)return;
 if(!confirm('Remover os elementos importados do arquivo '+entry.fileName+' deste navegador?'))return;
 const old=JSON.stringify(data);
 const removedIds=new Set(data.zones.filter(z=>z.importBatchId===batch).map(z=>z.id));
 data.zones=data.zones.filter(z=>z.importBatchId!==batch);
 data.ctos=data.ctos.filter(c=>c.importBatchId!==batch);
 data.referencePoints=data.referencePoints.filter(p=>p.importBatchId!==batch);
 data.assignments=data.assignments.filter(a=>!removedIds.has(a.zoneId));
 data.rules=data.rules.filter(r=>!removedIds.has(r.zone_id));
 data.imports=data.imports.filter(i=>i.id!==batch);
 if(!save()){data=JSON.parse(old);return;}
 state.importFocus=null;render();notify('Importação local removida.');
}

function coveragePage(){return `<div class="two-col"><div class="panel"><div class="panel-head"><div><div class="kicker">MALHA DE COBERTURA</div><h2>Territórios e CTOs</h2></div><span class="pill">${data.zones.length} ZONAS</span></div>${mapToolbar()}<div id="operation-map" class="map-viewport"></div>${mapFooter()}<div class="table-wrap"><table class="table"><thead><tr><th>CTO</th><th>Zona</th><th>Portas</th><th>Condição</th></tr></thead><tbody>${data.ctos.map(c=>`<tr><td><strong>${escape(c.name)}</strong></td><td>${escape(data.zones.find(z=>z.id===c.zone_id)?.name||'Sem área')}</td><td>${c.ports_free}</td><td>${c.example?'EXEMPLO • não validado':'Não verificado'}</td></tr>`).join('')}</tbody></table></div></div><div class="panel panel-pad"><div class="kicker">IMPORTAÇÃO TERRITORIAL</div><h2>Polígonos GeoJSON / KML</h2><p>Importe polígonos para organizar a área. Esses dados ficam somente neste navegador e não confirmam a cobertura da rede.</p><form id="zone-form" class="form-stack"><label class="input-label">Classificação dos polígonos importados<select class="input" name="audience">${segmentOptions()}</select></label><label class="input-label">Arquivo GeoJSON ou KML<input class="input" type="file" name="file" accept=".geojson,.json,.kml" required></label><button class="btn primary" type="submit">${svg('plus')} Importar polígonos</button></form><div class="divider"></div><h3 class="section-title">Territórios carregados</h3>${data.zones.map(z=>`<div class="mini-row"><span>${escape(z.name)}</span><label class="input-label">Público da área<select class="input" data-zone-audience="${z.id}">${segmentOptions(z.audience)}</select></label><button class="table-action danger" data-remove-zone="${z.id}">Remover</button></div>`).join('')}<div class="hint-block" style="margin-top:18px">A validação aqui confere apenas a estrutura do arquivo. Cobertura e capacidade dependem da fonte oficial da rede ST1.</div></div></div>`;}
function page(){return ({overview, routes:routesPage,people:peoplePage,products:productsPage,coverage:coveragePage,visits:visitsPage,planning:planningPage,reports:reportsPage,admin:adminPage,sales:salesPage,itinerary:itineraryPage})[state.page]();}
function stop(){if(state.timer)clearInterval(state.timer);state.timer=null;state.playing=false;}
function render(){if(state.map){state.map.destroy();state.map=null;}root.innerHTML=`<div class="shell">${chrome()}</div>`;const el=$('#operation-map');if(el){state.map=new OperationMap(el,{selectedPoint:state.page==='overview'?state.selectedPoint:null,onPick:p=>{if(state.page==='overview'){state.selectedPoint=p;state.result=null;render();notify('Ponto geográfico selecionado.');}},onSeller:id=>{state.sellerId=id;if(state.page==='overview')render();else if(state.page==='routes')render();},onCto:id=>notify('CTO '+id+' selecionada.')});state.map.updateData(asMapData());Object.entries(state.layers).forEach(([k,v])=>state.map.setLayer(k,v));if(state.page==='routes'){const p=dtr()[Math.min(state.routeIndex,dtr().length-1)];if(p)state.map.moveTo(p.lat,p.lon,14);drawRoute();}else if(state.page==='itinerary'){const stops=orderedStops();state.map.setRoute([stops]);if(stops.length)state.map.moveTo(stops[0].lat,stops[0].lon,14);}else (state.page==='coverage'&&state.importFocus?state.map.moveTo(state.importFocus.lat,state.importFocus.lon,13):state.map.jumpToRegion(state.mapRegion));}}
function drawRoute(){if(!state.map||state.page!=='routes')return;const pts=dtr(),idx=Math.max(0,Math.min(state.routeIndex,pts.length-1));state.map.setRoute([pts.slice(0,idx+1)],pts[idx]);const range=$('#route-range');if(range)range.value=String(idx);const t=$('#route-current-time');if(t)t.textContent=pts[idx]?pretty(pts[idx].at):'Sem dados de GPS';
 const cards=document.querySelectorAll('.route-stats .v');if(cards.length){cards[0].textContent=pts.length?idx+1:0;cards[1].textContent=(routeMeters(pts.slice(0,idx+1))/1000).toLocaleString('pt-BR',{maximumFractionDigits:2})+' km';cards[2].textContent=pts[idx]?pretty(pts[idx].at):'—';}
 const play=document.querySelector('[data-action="play"]');if(play)play.innerHTML=svg(state.playing?'pause':'play')+' '+(state.playing?'Pausar':'Reproduzir');}

function selectPage(page){stop();if(!titles[page])return;state.page=page;history.replaceState(null,'','#'+page);state.result=null;render();window.scrollTo({top:0,behavior:'instant'});}
function saveJSON(name,content,type='application/json'){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function exportRoute(){const pts=dtr(),seller=data.sellers.find(s=>s.id===state.sellerId);if(!pts.length)return notify('Nenhuma rota de exemplo disponível.','error');const out={type:'FeatureCollection',features:[{type:'Feature',geometry:{type:'LineString',coordinates:pts.map(p=>[p.lon,p.lat])},properties:{source:seller?.position?.source||'não informada',seller:seller?.name||'Sem vendedor',notice:'CENÁRIO FICTÍCIO. Coordenadas inventadas, sem rastreamento ou valor operacional.'}}]};saveJSON('rota-pap-exemplo.geojson',JSON.stringify(out,null,2));notify('GeoJSON exportado com os dados disponíveis.');}
function importZones(geo,audience=''){const list=geo?.type==='FeatureCollection'?geo.features:geo?.type==='Feature'?[geo]:[geo];if(!Array.isArray(list)||list.length<1||list.length>30)throw Error('Use entre 1 e 30 geometrias por arquivo.');let max=Math.max(0,...data.zones.map(x=>x.id)),created=[];
 for(const f of list){const g=f.geometry||f,valid=['Polygon','MultiPolygon'].includes(g.type);if(!valid||!Array.isArray(g.coordinates))throw Error('É obrigatório importar polígonos GeoJSON.');const polys=g.type==='Polygon'?[g.coordinates]:g.coordinates;for(const polygon of polys){for(const ring of polygon){if(!Array.isArray(ring)||ring.length<4||ring.length>12000)throw Error('Anel territorial inválido.');for(const p of ring){if(!Array.isArray(p)||p.length<2||!Number.isFinite(Number(p[0]))||!Number.isFinite(Number(p[1]))||Math.abs(Number(p[1]))>90||Math.abs(Number(p[0]))>180)throw Error('Coordenada de polígono inválida.');}}}const name=String(f.properties?.name||f.properties?.nome||`Importado ${max+1}`).slice(0,75);created.push({id:++max,name:name.replace(/^LOCAL\s*•\s*/i,''),audience:AREA_SEGMENTS[audience]?audience:'',category:AREA_SEGMENTS[audience]?audience:'PENDENTE',color:AREA_SEGMENTS[audience]?.color||'#7fcaa9',geometry:g});}
 data.zones.push(...created);save();return created.length;}
function kmlConvert(xmlText){const xml=new DOMParser().parseFromString(xmlText,'application/xml');if(xml.querySelector('parsererror'))throw Error('Arquivo KML inválido.');const features=[];for(const pm of xml.querySelectorAll('Placemark')){for(const poly of pm.querySelectorAll('Polygon')){const outer=poly.querySelector('outerBoundaryIs coordinates');if(!outer)continue;const ring=text=>text.trim().split(/\s+/).map(s=>s.split(',').slice(0,2).map(Number));const exterior=ring(outer.textContent);if(exterior.length&&!exterior[0].every((v,i)=>v===exterior.at(-1)[i]))exterior.push([...exterior[0]]);const holes=[...poly.querySelectorAll('innerBoundaryIs coordinates')].map(el=>ring(el.textContent));features.push({type:'Feature',properties:{name:pm.querySelector('name')?.textContent||'Setor KML'},geometry:{type:'Polygon',coordinates:[exterior,...holes]}});}}return {type:'FeatureCollection',features};}
root.addEventListener('click',ev=>{const t=ev.target.closest('button');if(!t)return;const city=t.dataset.mapCity;if(city&&MAP_REGIONS[city]){state.mapRegion=city;state.map?.jumpToRegion(city);document.querySelectorAll('[data-map-city]').forEach(b=>b.classList.toggle('selected',b.dataset.mapCity===city));return;}const nav=t.dataset.page;if(nav){if(t.dataset.selectSeller)state.sellerId=Number(t.dataset.selectSeller);selectPage(nav);return;}
 if(t.dataset.selectSeller){state.sellerId=Number(t.dataset.selectSeller);render();return;}
 if(t.dataset.planToggle){const plan=data.plans.find(p=>p.id===Number(t.dataset.planToggle));if(plan){plan.active=!plan.active;save();render();notify('Plano local atualizado.');}return;}
 if(t.dataset.planRemove){data.plans=data.plans.filter(p=>p.id!==Number(t.dataset.planRemove));data.rules=data.rules.filter(r=>r.plan_id!==Number(t.dataset.planRemove));save();render();notify('Plano removido.');return;}
 if(t.dataset.removeSeller){data.visits=data.visits.filter(v=>v.sellerId!==Number(t.dataset.removeSeller));data.assignments=data.assignments.filter(v=>v.sellerId!==Number(t.dataset.removeSeller));data.sellers=data.sellers.filter(s=>s.id!==Number(t.dataset.removeSeller));if(!data.sellers.some(s=>s.id===state.sellerId))state.sellerId=data.sellers[0]?.id||0;save();render();notify('Registro local removido.');return;}
 if(t.dataset.removeZone){const id=Number(t.dataset.removeZone);data.assignments=data.assignments.filter(a=>a.zoneId!==id);data.zones=data.zones.filter(z=>z.id!==id);data.ctos=data.ctos.filter(c=>c.zone_id!==id);data.rules=data.rules.filter(r=>r.zone_id!==id);save();render();notify('Território e vínculos locais removidos.');return;}
 switch(t.dataset.action){case 'play':if(state.playing){stop();render();return;}if(state.routeIndex>=dtr().length-1)state.routeIndex=0;state.playing=true;state.timer=setInterval(()=>{const points=dtr();if(!points.length){stop();render();return;}state.routeIndex++;if(state.routeIndex>=points.length){state.routeIndex=points.length-1;stop();render();return;}drawRoute();},350);render();break;
 case 'export':saveJSON('st1-sales-pap-exemplo.json',JSON.stringify({...data,notice:'EXEMPLO FICTÍCIO. Nunca importar como dado operacional do ST1 Sales.'},null,2));notify('Arquivo de exemplo exportado.');break;
 case 'route-export':exportRoute();break;
 case 'reset':if(!confirm('Descartar alterações deste navegador e restaurar o cenário fictício único?'))return;stop();data=defaultData();state.routeIndex=data.sellers[0]?.routePoints?.length-1||0;state.sellerId=data.sellers[0]?.id||0;itinerary.sellerId=state.sellerId;itinerary.date=localDate();state.team='all';state.mapRegion='sa_luis';state.positions={};state.selectedPoint=data.visits[0]?{lat:data.visits[0].lat,lon:data.visits[0].lon}:null;Object.assign(filters,{date:'',stage:'all',search:''});save();render();notify('Cenário fictício único restaurado.');break;
  case 'people-add':notify('O cadastro de profissionais depende da integração com o ST1 Sales.','error');break;
  }});
root.addEventListener('change',ev=>{const t=ev.target;if(t.dataset.zoneAudience){const z=data.zones.find(z=>z.id===Number(t.dataset.zoneAudience));if(z){z.audience=AREA_SEGMENTS[t.value]?t.value:'';z.category=z.audience||'PENDENTE';z.color=AREA_SEGMENTS[z.audience]?.color||'#7fcaa9';audit('Classificação territorial: '+z.name+' / '+(z.audience||'não classificada'));save();render();notify('Público da área atualizado.');}return;}
 if(t.dataset.layer){state.layers[t.dataset.layer]=t.checked;state.map?.setLayer(t.dataset.layer,t.checked);return;}
 if(t.id==='team-filter'){state.team=t.value;render();return;}
 if(t.id==='route-seller'){stop();state.sellerId=Number(t.value);state.routeIndex=0;render();return;}
 if(t.dataset.ruleZone){const zoneId=Number(t.dataset.ruleZone),planId=Number(t.dataset.rulePlan);data.rules=data.rules.filter(r=>!(r.zone_id===zoneId&&r.plan_id===planId));if(t.value!=='clear')data.rules.push({zone_id:zoneId,plan_id:planId,decision:t.value});save();notify('Regra local atualizada.');return;}
});
root.addEventListener('input',ev=>{if(ev.target.id==='route-range'){stop();state.routeIndex=Number(ev.target.value);drawRoute();}});
root.addEventListener('submit',async ev=>{ev.preventDefault();const form=ev.target,fields=new FormData(form);
 try{if(form.id==='plan-form'){const name=String(fields.get('name')||'').trim();if(name.length<3)throw Error('Nome obrigatório.');const raw=String(fields.get('price')||'');const price=raw===''?null:Number(raw);if(price!==null&&(!Number.isFinite(price)||price<0||price>100000))throw Error('Preço inválido.');const id=Math.max(0,...data.plans.map(p=>p.id))+1;data.plans.push({id,name:name.replace(/^LOCAL\s*•\s*/i,''),segment:String(fields.get('segment')),speed:String(fields.get('speed')||'—'),price,active:true});save();render();notify('Plano cadastrado.');}
 if(form.id==='eligibility-form'){state.result=evaluate({planId:fields.get('planId'),ctoId:fields.get('ctoId')});render();}
 if(form.id==='zone-form'){const file=fields.get('file');if(!(file instanceof File)||file.size<1)throw Error('Selecione um arquivo.');if(file.size>1_500_000)throw Error('Limite de 1,5 MB por arquivo.');const text=await file.text();const geo=file.name.toLowerCase().endsWith('.kml')?kmlConvert(text):JSON.parse(text);const count=importZones(geo,String(fields.get('audience')||''));render();notify(count+' polígonos importados localmente.');}}
 catch(e){notify(e.message||'Falha na operação.','error');}
});

function field(label,html){return `<label class="input-label">${label}${html}</label>`;}
function sellerSelect(){return `<select class="input" name="sellerId" required>${data.sellers.filter(s=>s.active).map(s=>`<option value="${s.id}">${escape(s.name)}</option>`).join('')}</select>`;}
function filterBar(){return `<form id="filter-form" class="filter-bar">${field('Buscar',`<input class="input" name="search" value="${escape(filters.search)}" placeholder="Local ou vendedor">`)}${field('Data',`<input class="input" type="date" name="date" value="${escape(filters.date)}">`)}${field('Etapa',`<select class="input" name="stage"><option value="all">Todas</option>${STAGES.map(v=>`<option ${filters.stage===v?'selected':''}>${v}</option>`).join('')}</select>`)}<button class="btn primary">Aplicar filtros</button><button type="button" class="btn ghost" data-action="clear-filters">Limpar</button></form>`;}
function filtered(){return filterVisits(data,{...filters,team:state.team});}
function visitsPage(){const visits=filtered();return `<div class="panel panel-pad">${filterBar()}<div class="split-toolbar"><h2>Agenda e funil <span class="pill">${visits.length} registro(s) fictício(s)</span></h2><button class="btn ghost" data-action="visits-csv">${svg('download')} Exportar CSV</button></div><div class="kanban">${STAGES.map(stage=>`<section class="kanban-column"><h3>${stage} <span>${visits.filter(v=>v.stage===stage).length}</span></h3>${visits.filter(v=>v.stage===stage).map(v=>`<article class="visit-card"><small>${escape(v.date)} · ${escape(v.at)}</small><h3>${escape(v.place)}</h3><p>${escape(data.sellers.find(s=>s.id===v.sellerId)?.name||'Sem vendedor')}</p><p>${escape(v.notes||'Sem observação')}</p><label class="input-label">Mover para<select class="input" data-visit-stage="${v.id}">${STAGES.map(x=>`<option ${x===v.stage?'selected':''}>${x}</option>`).join('')}</select></label></article>`).join('')||'<p class="empty">Nenhuma visita nesta etapa.</p>'}</section>`).join('')}</div></div><div class="panel panel-pad section-gap"><h2>Registrar visita (rascunho local)</h2><p>Os registros ficam neste navegador, sem sincronização. Não insira dados pessoais até habilitar a autenticação.</p><form id="visit-form" class="form-grid">${field('Vendedor',sellerSelect())}${field('Local','<input class="input" name="place" required maxlength="100" placeholder="Nome do local">')}${field('Data',`<input class="input" name="date" type="date" required value="${localDate()}">`)}${field('Horário','<input class="input" name="at" type="time" required value="09:00">')}${field('Latitude','<input class="input" name="lat" type="number" step="any" min="-85" max="85" placeholder="Latitude" required>')}${field('Longitude','<input class="input" name="lon" type="number" step="any" min="-180" max="180" placeholder="Longitude" required>')}${field('Etapa',`<select class="input" name="stage">${STAGES.map(v=>`<option>${v}</option>`).join('')}</select>`)}${field('Observação','<textarea name="notes" maxlength="500" placeholder="Observação da visita"></textarea>')}<button class="btn primary" ${data.sellers.length?'':'disabled'}>Salvar rascunho</button></form></div>`;}
function planningPage(){return `<div class="two-col"><section class="panel panel-pad"><div class="kicker">DISTRIBUIÇÃO TERRITORIAL</div><h2>Agenda de campo</h2><button class="btn primary" data-page="itinerary">Montar roteiro de visitas</button>${data.assignments.length?data.assignments.map(a=>`<article class="assignment"><span class="pill">${escape(a.date)}</span><h3>${escape(data.zones.find(z=>z.id===a.zoneId)?.name||'Território removido')}</h3><p>${escape(data.sellers.find(s=>s.id===a.sellerId)?.name||'Vendedor removido')}</p><div class="mini-row"><span>Meta de visitas</span><strong>${a.target}</strong></div><div class="mini-row"><span>Situação</span><strong>${escape(a.status)}</strong></div><button class="btn ghost" data-assignment="${a.id}">${a.status==='Planejada'?'Concluir planejamento':'Reabrir planejamento'}</button></article>`).join(''):'<div class="empty">Nenhuma atividade planejada. Distribua o primeiro território ao lado.</div>'}</section><section class="panel panel-pad"><h2>Planejar território</h2><form id="assignment-form" class="form-stack">${field('Vendedor',sellerSelect())}${field('Território',`<select name="zoneId" class="input" required>${data.zones.map(z=>`<option value="${z.id}">${escape(z.name)}</option>`).join('')}</select>`)}${field('Data',`<input type="date" name="date" class="input" value="${localDate()}" required>`)}${field('Meta de visitas','<input type="number" class="input" name="target" min="1" max="500" value="20" required>')}<button class="btn primary">Salvar planejamento local</button></form><div class="hint-block section-gap">A alocação organiza o trabalho. Não calcula a melhor rota nem confirma cobertura comercial.</div></section></div>`;}
function reportsPage(){const visits=filtered(),m=metrics(visits);return `<div class="panel panel-pad">${filterBar()}<label class="input-label">Equipe<select class="input" id="team-filter">${teamOptions(state.team)}</select></label></div><div class="stats section-gap">${stat('VISITAS',m.total,'Dados fictícios no filtro')}${stat('REALIZADAS',m.done,'Etapas diferentes de planejada')}${stat('VENDAS REGISTRADAS',m.sales,'Exemplo fictício; não é venda real')}${stat('CONVERSÃO',m.conversion.toFixed(1)+'%','Amostra fictícia; não é KPI real',true)}</div><div class="two-col"><section class="panel panel-pad"><h2>Distribuição por etapa</h2>${STAGES.map(stage=>{const count=visits.filter(v=>v.stage===stage).length;return `<div class="mini-row"><span>${stage}</span><strong>${count}</strong></div><progress max="${Math.max(1,m.total)}" value="${count}" aria-label="${stage}: ${count}"></progress>`;}).join('')}</section><section class="panel panel-pad"><h2>Resultado por vendedor</h2><div class="table-wrap"><table class="table"><thead><tr><th>Vendedor</th><th>Visitas</th><th>Realizadas</th><th>Vendas locais</th></tr></thead><tbody>${data.sellers.filter(s=>state.team==='all'||s.team===state.team).map(s=>{const m=metrics(visits.filter(v=>v.sellerId===s.id));return `<tr><td>${escape(s.name)}</td><td>${m.total}</td><td>${m.done}</td><td>${m.sales}</td></tr>`;}).join('')}</tbody></table></div><button class="btn ghost section-gap" data-action="visits-csv">Exportar registros filtrados</button></section></div>`;}
function adminPage(){return `<div class="two-col"><section class="panel panel-pad"><div class="kicker">DADOS E AMBIENTE</div><h2>Ambiente e integrações</h2><p>O cenário único é fictício e permanece somente neste navegador. Não existe sincronização de GPS, cadastros ou visitas desta central com o ST1 Sales.</p><div class="mini-row"><span>Persistência</span><strong>LocalStorage / navegador</strong></div><div class="mini-row"><span>GPS de colaboradores</span><strong>Somente exemplo fictício</strong></div><div class="mini-row"><span>API e banco remoto</span><strong>Pendente de implantação</strong></div><div class="mini-row"><span>IXC / CRM / vendas</span><strong>Não conectados</strong></div><div class="split-toolbar section-gap"><button class="btn primary" data-action="export">Exportar exemplo</button><button class="btn ghost" data-action="reset">Restaurar exemplo</button></div><details class="section-gap"><summary>Perfis previstos para o ambiente autenticado</summary><p>Diretoria: visão consolidada. Gerência: operação e cadastros. Supervisão: equipe atribuída. Vendedor: própria jornada e visitas. As permissões deverão ser aplicadas pela API, não apenas pelos menus.</p></details></section><section class="panel panel-pad"><h2>Histórico local de alterações</h2><p>Histórico local que não substitui auditoria do servidor.</p>${data.activity.map(a=>`<div class="timeline-entry"><span class="node"></span><div><strong>${escape(a.message)}</strong><small>${pretty(a.at)}</small></div></div>`).join('')||'<div class="empty">As novas visitas e alocações aparecerão aqui.</div>'}</section></div>`;}
root.addEventListener('change',ev=>{const t=ev.target;if(t.dataset.visitStage){const v=data.visits.find(v=>v.id===Number(t.dataset.visitStage));if(v&&STAGES.includes(t.value)){v.stage=t.value;audit('Visita local '+v.id+': '+v.stage);save();render();notify('Etapa atualizada.');}}});
root.addEventListener('click',ev=>{const t=ev.target.closest('button');if(!t)return;
 if(t.dataset.assignment){const a=data.assignments.find(a=>a.id===Number(t.dataset.assignment));if(a){a.status=a.status==='Planejada'?'Concluída':'Planejada';audit('Planejamento local '+a.id+': '+a.status);save();render();}}
 if(t.dataset.action==='clear-filters'){Object.assign(filters,{date:'',stage:'all',search:''});state.team='all';render();}
 if(t.dataset.action==='visits-csv'){saveJSON('visitas-locais.csv',csv([['Origem','Data','Hora','Vendedor','Local','Etapa','Observação'],...filtered().map(v=>[v.example?'EXEMPLO':'LOCAL',v.date,v.at,data.sellers.find(s=>s.id===v.sellerId)?.name,v.place,v.stage,v.notes])]),'text/csv;charset=utf-8');notify('Registros filtrados exportados.');}
});
root.addEventListener('submit',ev=>{const form=ev.target,f=Object.fromEntries(new FormData(form));try{
 if(form.id==='filter-form'){Object.assign(filters,f);render();}
 if(form.id==='visit-form'){const visit=validateVisit(f,data);visit.id=Math.max(0,...data.visits.map(v=>v.id))+1;data.visits.push(visit);audit('Visita local '+visit.id+' registrada');save();render();notify('Visita salva neste navegador.');}
 if(form.id==='assignment-form'){const sellerId=Number(f.sellerId),zoneId=Number(f.zoneId),target=Number(f.target);if(!data.sellers.some(s=>s.id===sellerId&&s.active)||!data.zones.some(z=>z.id===zoneId)||!f.date||!Number.isInteger(target)||target<1||target>500)throw Error('Verifique vendedor, território, data e meta.');if(data.assignments.some(a=>a.sellerId===sellerId&&a.zoneId===zoneId&&a.date===f.date))throw Error('Este vendedor já está alocado neste território e data.');data.assignments.push({id:Math.max(0,...data.assignments.map(a=>a.id))+1,sellerId,zoneId,target,date:f.date,status:'Planejada'});audit('Território alocado localmente');save();render();notify('Planejamento salvo.');}
 }catch(e){notify(e.message,'error');}});
window.addEventListener('hashchange',()=>selectPage(location.hash.slice(1)));
state.page=titles[location.hash.slice(1)]?location.hash.slice(1):'overview';


function salesPage(){return `<div class="two-col"><section class="panel panel-pad"><div class="kicker">DADOS COMERCIAIS</div><h2>Sales conectado à operação PAP</h2><p>Consulte usuários, prospecções, negociações e a rede com sua conta individual do Sales.</p><a class="btn primary" href="./sales.html">Entrar no Sales</a><div class="divider"></div><h3>Consultas por contexto</h3><div class="split-toolbar"><a class="btn ghost" href="./sales.html#users">Usuários e vínculos</a><a class="btn ghost" href="./sales.html#coverage">CTOs do Sales</a><a class="btn ghost" href="./sales.html#feasibility">Viabilidade do imóvel</a><a class="btn ghost" href="./sales.html#deals">Negociações</a></div></section><section class="panel panel-pad"><h2>Situação da integração</h2><div class="mini-row"><span>Consultas Sales</span><strong>Login individual disponível</strong></div><div class="mini-row"><span>GPS real e jornadas</span><strong>Aguardam conexão móvel</strong></div><div class="mini-row"><span>Roteiros e visitas desta central</span><strong>Rascunhos locais</strong></div><p class="hint-block">O exemplo de campo é inteiramente fictício e fica separado das consultas autenticadas ao ST1 Sales. Não deve ser usado para decisões comerciais.</p></section></div>`;}
function itineraryKey(){return itinerary.sellerId+':'+itinerary.date;}
function orderedStops(){const visits=data.visits.filter(v=>v.sellerId===itinerary.sellerId&&v.date===itinerary.date);const order=data.itineraries[itineraryKey()]||[];return visits.sort((a,b)=>{const ai=order.indexOf(a.id),bi=order.indexOf(b.id);return (ai<0?100000+a.id:ai)-(bi<0?100000+b.id:bi);});}
function itineraryPage(){const stops=orderedStops();return `<div class="panel panel-pad"><form id="itinerary-filter" class="filter-bar"><label class="input-label">Vendedor<select name="sellerId" class="input">${data.sellers.map(s=>`<option value="${s.id}" ${itinerary.sellerId===s.id?'selected':''}>${escape(s.name)}</option>`).join('')}</select></label><label class="input-label">Data<input class="input" name="date" type="date" value="${itinerary.date}" required></label><button class="btn primary">Carregar visitas</button><button class="btn ghost" type="button" data-page="visits">Registrar visita</button></form></div><div class="map-grid-layout section-gap"><section class="panel"><div class="panel-head"><h2>Percurso planejado</h2><span class="pill">${stops.length} PARADAS</span></div><div id="operation-map" class="map-viewport"></div><div class="hint-block">A linha conecta as paradas na ordem escolhida. Não representa trajeto viário, navegação, GPS coletado ou otimização de rota.</div></section><section class="panel panel-pad"><h2>Ordem das visitas</h2>${stops.map((v,i)=>`<article class="visit-card"><div class="kicker">PARADA ${i+1} · ${escape(v.at)}</div><h3>${escape(v.place)}</h3><p>${escape(v.stage)} · ${Number(v.lat).toFixed(5)}, ${Number(v.lon).toFixed(5)}</p><div class="split-toolbar"><button class="btn ghost" data-stop="${v.id}" data-direction="-1" ${i===0?'disabled':''} aria-label="Subir ${escape(v.place)}">Subir</button><button class="btn ghost" data-stop="${v.id}" data-direction="1" ${i===stops.length-1?'disabled':''} aria-label="Descer ${escape(v.place)}">Descer</button></div></article>`).join('')||'<div class="empty">Nenhuma visita disponível. A sincronização ou um registro local é necessária para montar o roteiro.</div>'}<button class="btn primary" data-action="itinerary-export" ${stops.length<2?'disabled':''}>Exportar roteiro GeoJSON</button></section></div>`;}
root.addEventListener('submit',e=>{if(e.target.id!=='itinerary-filter')return;const f=new FormData(e.target);itinerary.sellerId=Number(f.get('sellerId'));itinerary.date=String(f.get('date'));render();});
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.stop){const stops=orderedStops(),index=stops.findIndex(v=>v.id===Number(b.dataset.stop)),next=index+Number(b.dataset.direction);if(index<0||next<0||next>=stops.length)return;[stops[index],stops[next]]=[stops[next],stops[index]];data.itineraries[itineraryKey()]=stops.map(v=>v.id);audit('Ordem do roteiro local atualizada');save();render();}if(b.dataset.action==='itinerary-export'){const stops=orderedStops();if(stops.length<2)return;saveJSON('roteiro-planejado-local.geojson',JSON.stringify({type:'FeatureCollection',features:[{type:'Feature',properties:{source:'LOCAL',kind:'planned_straight_segments',date:itinerary.date},geometry:{type:'LineString',coordinates:stops.map(v=>[v.lon,v.lat])}},...stops.map((v,i)=>({type:'Feature',properties:{source:'LOCAL',order:i+1,name:v.place,stage:v.stage},geometry:{type:'Point',coordinates:[v.lon,v.lat]}}))]},null,2));}});

render();
